tcome_2 != 'Seçiniz...'",                        selectInput("Linearity_exist_2", "Verileriniz doğrusallık varsayımlarını karşılıyor mu?",                                    choices = c("Seçiniz...",                                                "Evet. Doğrusal model kullan.",                                                "Hayır. Doğrusal olmayan model kullan.")),                      br(),                      p("Hatırlatma: Grup üyeliklerine yönelik doğrusal tahmin modelleri, sürekli tahmin edicilerle iyi çalışır. Kesikli tahminciler varsa 'kukla değişken atama' gibi bazı istatistiksel düzeltmelerin yapılması gerekir. Öte yandan grup üyeliklerine yönelik doğrusal olmayan tahmin modelleri sürekli veya kesikli değişkenlerle yeterince iyi çalışmaktadır.", class = "conditional-text")                      )                    )                  ),                  # Add conditional follow-up inquiries for Module 8                  conditionalPanel(                    condition = "input.module == 'Modül 8. Veri indirgeme'",                    selectInput("data_Tipi", "Ne tür maddeleriniz veya göstergeleriniz var?",                                choices = c("Seçiniz...",                                            "Metrik veya sürekli",                                             "Sıralı",                                            "İkili veya çoklu sınıflamalı")),                    conditionalPanel(                      condition = "input.data_Tipi != 'Seçiniz...'",                      selectInput("assumption_meet", "Verileriniz çokdeğişkenli normallik ve doğrusallık gibi temel varsayımları veya yeterli örneklem büyüklüğünü karşılıyor mu?",                                  choices = c("Seçiniz...",                                               "Evet. Veri setimde ciddi düzeyde bir varsayımsal ihlal yok.",                                               "Hayır. Veri setimde normallik ve doğrusallık ile ilişkili bazı ihlaler var.",              