h edilir ve ciddi varsayım ihlalleri olmadığı sürece ölçekleme için yeterli olur.", class = "conditional-text"),                        p("Dirençli (robust) teknikler, nomallik ihlalleri gibi dağılım yapısıyla iligili varsayımsal ihlaller dışındaki varsayımsal ihlallerle başa çıkmada yardımcı olabilir.", class = "conditional-text"),                        p("Doğrusal olmayan modeller kendi varsayımsal dağılım özelliklerine göre çalışır. Bu modellerin normallik veya doğrusallık gibi varsayımları karşılaması gerekmez.", class = "conditional-text")                      )                    )                  ),                  # Add conditional follow-up inquiries for Module 10                  conditionalPanel(                    condition = "input.module == 'Modül 10. Ölçek geliştirme ve uyarlamada madde ve test analizleri'",                    selectInput("theory_type", " Hangi test kuramını esas alıyorsunuz?",                                choices = c("Seçiniz...", "Klasik Test Teorisi (KTK)", "Madde Tepki Kuramı (MTK)")),                    p("Hatırlatma: KTK, hem MTK modellerini hem MTK tabanlı olmayan modelleri içeren genel bir çerçevedir. MTK ise tam anlamıyla bir test teorisi olmaktan çok, bir ölçekleme yaklaşımı olarak değerlendirilebilir.", class = "conditional-text"),                    br(),                    conditionalPanel(                      condition = "input.theory_type != 'Seçiniz...'",                      selectInput("study_Tipi", "Veri üzerinde ne tür bir çalışma yapmayı planlıyorsunuz?",                                  choices = c("Seçiniz...",                                               "Betimleme amaçlı olarak madde ve test istatistiklerini elde etme",                                              "Güvenirlik çalışmaları",                                               "Geçerlik çalışmaları")),                      conditionalPanel(                        condition = "input.theory_type == 'Klasik Test Teorisi (KTK)' && input.study_Tipi == 'Güvenirlik çalışmaları'",                        selectInput("reliability_Tipi", "Veri üzerinde ne tür bir güvenirlik çalışması yapmayı planlıyorsunuz?",                                    choices = c("Seçiniz...",                                                 "İçtutarlılık",                                                "Test tekrar test",                                                 "Eşdeğer formlar",                                                "Puanlayıcı güvenirliği"))                      ),                           conditionalPanel(                        condition = "input.study_Tipi == 'Geçerlik çalışmaları'",                        selectInput("validity_type_1", "Veri üzerinde ne tür bir geçerlik çalışması yapmayı planlıyorsunuz?",                                    choices = c("Seçiniz...",                                                 "Kapsam geçerliği",                                                "Ölçüt dayanaklı geçerlik",                                                 "Ayırıcılık",                                                "Yapı geçerliği")),                        conditionalPanel(                          condition = "input.validity_type_1 == 'Yapı geçerliği'",                          selectInput("validity_type_2", "Veri üzerinde ne tür bir yapı geçerliği çalışması yapmayı planlıyorsunuz?",                                      choices = c("Seçiniz...",                                                   "Yapısal geçerlik",                                                  "Değişen madde fonksiyonlaşması (DMF)",                                                   "Test eşitleme",                                                  "Ölçme değişmezliği"))                        )                      ),                      conditionalPanel(                        condition = "input.theory_type == 'Madde Tepki Kuramı (MTK)' &&                                     input.study_Tipi == 'Betimleme amaçlı olarak madde ve test istatistiklerini elde etme'",                        selectInput("dimension_Tipi_1", "Verilerinizin boyut yapısı nedir?",                                    choices = c("Seçiniz...", "Tekboyutlu", "Çokboyutlu")),                        conditionalPanel(                          condition = "input.dimension_Tipi_1 == 'Tekboyutlu'",                          selectInput("item_Tipi_1", "Ne tipte maddeleriniz var?",                                      choices = c("Seçiniz...", "İki kategorili", "Çok kategorili", "Karma"))                        )                      ),                      conditionalPanel(                        condition = "input.reliability_Tipi == 'İçtutarlılık'",                        selectInput("dimension_Tipi_2", "Verilerinizin boyut yapısı nedir?",                                    choices = c("Seçiniz...", "Tekboyutlu", "Çokboyutlu")),                        conditionalPanel(                          condition = "input.dimension_Tipi_2 == 'Tekboyutlu'",                          selectInput("item_Tipi_2", "Ne tipte maddeleriniz var?",                                      choices = c("Seçiniz...", "İki kategorili", "Çok kategorili", "Karma"))                        )                      ),                      conditionalPanel(                        condition = "input.reliability_Tipi == 'Test tekrar test' || input.reliability_Tipi == 'Eşdeğer formlar'",                        selectInput("item_Tipi_3", "Ne tipte maddeleriniz var?",                                    choices = c("Seçiniz...", "İki kategorili", "Çok kategorili", "Karma"))                      ),                      conditionalPanel(                        condition = "input.theory_type == 'Madde Tepki Kuramı (MTK)' &&                                     input.study_Tipi == 'Güvenirlik çalışmaları'",                        selectInput("dimension_Tipi_3", "Verilerinizin boyut yapısı nedir?",                        