      font-size: 14px;     }    .switch button:hover {      background-color: lightyellow;    }    .app-content {      margin-top: 20px; /* Space below the header */    }  ")))server <- function(input, output, session) {  # Reactive value to keep track of the mode  mode <- reactiveVal("horizontal")  # Change mode when toggle button is pressed  observeEvent(input$toggle, {    mode(ifelse(mode() == "horizontal", "vertical", "horizontal"))  })  # Dynamic UI rendering  output$dynamic_ui <- renderUI({    if (mode() == "horizontal") {      horizontal_ui    } else {      vertical_ui    }  })  # Shared server-side logic for both modes  # Reset inputs when the module changes  observeEvent(input$module, {    if (input$module != "") {  # Check if module is selected      #Module 1 variables      updateSelectInput(session, "doc_pool_size", selected = "Seçiniz...")      updateSelectInput(session, "themes_clear", selected = "Seçiniz...")      #Module 2 variables      updateSelectInput(session, "assumption_check", selected = "Seçiniz...")      #Module 3 variables      updateSelectInput(session, "number_of_dv", selected = "Seçiniz...")      updateSelectInput(session, "number_of_group", selected = "Seçiniz...")      updateSelectInput(session, "existence_of_cv", selected = "Seçiniz...")      #Module 4 variables      updateSelectInput(session, "experiment_design", selected = "Seçiniz...")      updateSelectInput(session, "experiment_dv", selected = "Seçiniz...")      updateSelectInput(session, "experiment_measures", selected = "Seçiniz...")      updateSelectInput(session, "experiment_cv", selected = "Seçiniz...")      #Module 5 variables      updateSelectInput(session, "purpose_of_rm", selected = "Seçiniz...")      #Module 6 variables      updateSelectInput(session, "Tipi_corr", selected = "Seçiniz...")      updateSelectInput(session, "measurement_level_1", selected = "Seçiniz...")      updateSelectInput(session, "measurement_level_2", selected = "Seçiniz...")      #Module 7 variables      updateSelectInput(session, "purpose_of_design", selected = "Seçiniz...")      updateSelectInput(session, "Type_of_outcome_1", selected = "Seçiniz...")      updateSelectInput(session, "Type_of_predictor", selected = "Seçiniz...")      updateSelectInput(session, "Linearity_exist_1", selected = "Seçiniz...")      updateSelectInput(session, "Tipi_of_outcome_2", selected = "Seçiniz...")      updateSelectInput(session, "Linearity_exist_2", selected = "Seçiniz...")      #Module 8 variables      updateSelectInput(session, "data_Tipi", selected = "Seçiniz...")      updateSelectInput(session, "assumption_meet", selected = "Seçiniz...")      #Module 9 variables      updateSelectInput(session, "Ölçekleme_purpose", selected = "Seçiniz...")      updateSelectInput(session, "dimension_Tipi", selected = "Seçiniz...")      updateSelectInput(session, "model_Tipi", selected = "Seçiniz...")      #Module 10 variables      updateSelectInput(session, "theory_type", selected = "Seçiniz...")      updateSelectInput(session, "study_Tipi", selected = "Seçiniz...")      updateSelectInput(session, "reliability_Tipi", selected = "Seçiniz...")      updateSelectInput(session, "validity_type_1", selected = "Seçiniz...")      updateSelectInput(session, "validity_type_2", selected = "Seçiniz...")      updateSelectInput(session, "dimension_Tipi_1", selected = "Seçiniz...")      updateSelectInput(session, "item_Tipi_1", selected = "Seçiniz...")      updateSelectInput(session, "dimension_Tipi_2", selected = "Seçiniz...")      updateSelectInput(session, "item_Tipi_2", selected = "Seçiniz...")      updateSelectInput(session, "item_Tipi_3", selected = "Seçiniz...")      updateSelectInput(session, "dimension_Tipi_3", selected = "Seçiniz...")    }  })  # Reset inputs when the purpose changes in module-7  observeEvent(input$purpose_of_design, {    if (input$purpose_of_design != "") {  # Check if module is selected      updateSelectInput(session, "Type_of_outcome_1", selected = "Seçiniz...")      updateSelectInput(session, "Type_of_predictor", selected = "Seçiniz...")      updateSelectInput(session, "Linearity_exist_1", selected = "Seçiniz...")      updateSelectInput(session, "Tipi_of_outcome_2", selected = "Seçiniz...")      updateSelectInput(session, "Linearity_exist_2", selected = "Seçiniz...")    }  })  # Reset inputs when the theory Tipi changes in module-10  observeEvent(input$theory_type, {    if (input$theory_type != "") {  # Check if theory_type is selected      updateSelectInput(session, "study_Tipi", selected = "Seçiniz...")      updateSelectInput(session, "reliability_Tipi", selected = "Seçiniz...")      updateSelectInput(session, "validity_type_1", selected = "Seçiniz...")      updateSelectInput(session, "validity_type_2", selected = "Seçiniz...")      updateSelectInput(session, "dimension_Tipi_1", selected = "Seçiniz...")      updateSelectInput(session, "item_Tipi_1", selected = "Seçiniz...")      updateSelectInput(session, "dimension_Tipi_2", selected = "Seçiniz...")      updateSelectInput(session, "item_Tipi_2", selected = "Seçiniz...")      updateSelectInput(session, "item_Tipi_3", selected = "Seçiniz...")      updateSelectInput(session, "dimension_Tipi_3", selected = "Seçiniz...")    }  })  # Reset inputs when the study changes in module-10  observeEvent(input$study_Tipi, {    if (input$study_Tipi != "") {  # Check if study_Tipi is selected      updateSelectInput(session, "reliability_Tipi", selected = "Seçiniz...")      updateSelectInput(session, "validity_type_1", selected = "Seçiniz...")      updateSelectInput(session, "validity_type_2", selected = "Seçiniz...")      updateSelectInput(session, "dimension_Tipi_1", selected = "Seçiniz...")      updateSelectInput(session, "item_Tipi_1", selected = "Seçiniz...")      updateSelectInput(session, "dimension_Tipi_2", selected = "Seçiniz...")      updateSelectInput(session, "item_Tipi_2", selected = "Seçiniz...")      updateSelectInput(session, "item_Tipi_3", selected = "Seçiniz...")      updateSelectInput(session, "dimension_Tipi_3", selected = "Seçiniz...")    }  })  # Render the appropriate technique suggestion  output$technique_suggestion <- renderUI({    ##Module-1 for Column-3    if (input$module == "Modül 1. Yazılı dokümanların analizi") {      if (input$doc_pool_size %in% c("Küçük", "Orta") && input$themes_clear == "Belli") {        p("Önerebileceğim teknik: ", strong("Basit Doküman Analizi."))      } else if (input$doc_pool_size == "Küçük" && input$themes_clear == "Belli değil") {        p("Önerebileceğim teknik: ", strong("Tematik Doküman Analizi."))      } else if (input$doc_pool_size == "Orta" && input$themes_clear == "Belli değil") {        p("Önerebileceğim teknik: ", strong("Tematik Doküman Analizi "), "veya ", strong("Basit İçerik Analizi."))      } else if (input$doc_pool_size == "Büyük" && input$themes_clear == "Belli") {        p("Önerebileceğim teknik: ", " tema veya alt başlıklarınıza uygun hazır kodlamalarla yürütebileceğiniz", strong("İçerik Analizi"))      } else if (input$doc_pool_size == "Büyük" && input$themes_clear %in% c("Belli", "Belli değil")) {        p("Önerebileceğim teknik: ", strong("İçerik Analizi."))      } else if (input$doc_pool_size == "Çok büyük" && input$themes_clear %in% c("Belli", "Belli değil")) {        p("Önerebileceğim teknik: ", strong("Text Mining"), " stratejileri.")      } else {        p("Bir öneri alabilmek için, lütfen ilgili sorgulamaları tamamlayınız..")      }    ##Module-2 for Column-3    } else if (input$module == "Modül 2. Temel varsayımların testi") {      if (input$assumption_check == "Normallik") {        p("Aşağıda sıraladığım teknikleri önerebilirim.",           br(),          br(),          strong("Görsel inceleme:"),          br(),          "- Histogram",          br(),          "- Q-Q grafiği",          br(),          "- Kutu-çizgi grafiği",          br(),          br(),
          strong("Betimsel İstatistikler:"),
